def bear_fur(bears):
    if len(bears) != 2:
        return 'unknown'

    bear1, bear2 = bears[0].lower(), bears[1].lower()

    valid_colors = {'black', 'brown', 'white'}

    if bear1 not in valid_colors or bear2 not in valid_colors:
        return 'unknown'

    if bear1 == bear2:
        return bear1

    if (bear1 == 'black' and bear2 == 'brown') or (bear1 == 'brown' and bear2 == 'black'):
        return 'dark brown'

    if (bear1 == 'black' and bear2 == 'white') or (bear1 == 'white' and bear2 == 'black'):
        return 'grey'

    if (bear1 == 'brown' and bear2 == 'white') or (bear1 == 'white and bear2 == 'brown'):
        return 'light brown'

    return 'unknown'
